     1	import { damagedItems } from "./damaged-item.js";
     2	import type { Item } from "./policy.js";
     3	import { payoutRoundedInMHPCOsFavour } from "./rounding.js";
     4	import { reimbursementRateOf } from "./reimbursement-clause.js";
     5	
     6	export interface Damage {
     7	  readonly itemType: string;
     8	  readonly amount: number;
     9	}
    10	
    11	export interface ClaimResult {
    12	  readonly payout: number;
    13	  readonly remainingCap: number;
    14	}
    15	
    16	/**
    17	 * The policyholder bears a deductible on each damaged item, so an incident
    18	 * that damages several items bears it several times -- once per damage
    19	 * entry, which is why the payout is accumulated per entry rather than off
    20	 * the incident's total.
    21	 */
    22	const DEDUCTIBLE = 100;
    23	
    24	/**
    25	 * A payout is money the MHPCO pays out, so it floors at nothing: the
    26	 * deductible can reduce a payout to zero, but a damage smaller than the
    27	 * deductible never turns into a debt owed to the MHPCO.
    28	 */
    29	const NOTHING_PAID_OUT = 0;
    30	
    31	/** What one damage settles at: the reimbursed share, less the deductible. */
    32	function payoutForDamage(damagedItem: Item, damage: Damage): number {
    33	  const reimbursed = damage.amount * reimbursementRateOf(damagedItem);
    34	  return Math.max(reimbursed - DEDUCTIBLE, NOTHING_PAID_OUT);
    35	}
    36	
    37	/**
    38	 * What an incident settles at: each damage entry is settled on its own --
    39	 * under the clauses of the item it hit, and bearing its own deductible --
    40	 * and the entries accumulate. An incident that damages nothing settles at
    41	 * nothing.
    42	 */
    43	function incidentPayout(
    44	  items: readonly Item[],
    45	  damages: readonly Damage[],
    46	): number {
    47	  const hit = damagedItems(
    48	    items,
    49	    damages.map((damage) => damage.itemType),
    50	  );
    51	  return damages.reduce(
    52	    (total, damage, entry) => total + payoutForDamage(hit[entry], damage),
    53	    NOTHING_PAID_OUT,
    54	  );
    55	}
    56	
    57	/** What a draw against the cap takes, and what it leaves behind. */
    58	interface CapDraw {
    59	  readonly drawn: number;
    60	  readonly remainingCap: number;
    61	}
    62	
    63	/**
    64	 * The policy pays no more than its cap still allows, so a payout the cap
    65	 * cannot cover is reduced to what is left of it -- and once the cap is
    66	 * exhausted it draws nothing at all.
    67	 *
    68	 * What a draw takes and what it leaves are one fact about the cap, stated
    69	 * here together so that neither can be revised without the other.
    70	 *
    71	 * The cap is a separate limit from the clauses and the deductible: those
    72	 * decide what the MHPCO owes for a damage, whereas the cap decides how much
    73	 * a policy can still pay out at all, and the MHPCO revises the two on their
    74	 * own schedules -- which is why drawing against the cap is stated apart from
    75	 * what a damage settles at.
    76	 */
    77	function drawAgainstCap(capBeforeClaim: number, desiredPayout: number): CapDraw {
    78	  const drawn = Math.min(desiredPayout, capBeforeClaim);
    79	  return { drawn, remainingCap: capBeforeClaim - drawn };
    80	}
    81	
    82	/**
    83	 * What the incident settles at as a final payout: whole G, rounded in the
    84	 * MHPCO's favour.
    85	 *
    86	 * The rounding happens here, before the cap is drawn against, rather than on
    87	 * whatever the draw yields. The clauses and the deductible are the
    88	 * calculation, and its result is the final payout the spec has rounded; the
    89	 * cap is a limit applied to that finished amount, not a further step of the
    90	 * calculation. Rounding first is also what keeps the cap's ledger honest:
    91	 * the policy is debited exactly the whole G it pays out, so the payout and
    92	 * the remaining cap always add back up to the cap before the claim.
    93	 *
    94	 * Under the present rules the alternative ordering is indistinguishable --
    95	 * a cap is always whole G, so a draw that binds yields that same whole
    96	 * number either way -- which is precisely why the choice is stated here by
    97	 * name instead of being left implicit in the order of two calls.
    98	 */
    99	function finalPayoutFor(
   100	  items: readonly Item[],
   101	  damages: readonly Damage[],
   102	): number {
   103	  return payoutRoundedInMHPCOsFavour(incidentPayout(items, damages));
   104	}
   105	
   106	/**
   107	 * Settling an incident against the policy that covers it: what the incident
   108	 * settles at, and what it leaves of the policy's cap.
   109	 */
   110	export function claim(
   111	  items: readonly Item[],
   112	  damages: readonly Damage[],
   113	  capBeforeClaim: number,
   114	): ClaimResult {
   115	  const { drawn, remainingCap } = drawAgainstCap(
   116	    capBeforeClaim,
   117	    finalPayoutFor(items, damages),
   118	  );
   119	  return { payout: drawn, remainingCap };
   120	}
